function preview_escape($text){return htmlspecialchars((string)$text,ENT_QUOTES,'UTF-8');}
function preview_xml($text){$doc=new DOMDocument();if(!$doc->loadXML($text,LIBXML_NONET))throw new RuntimeException('Invalid document.');return $doc;}
