try{$zip=new PharData(__DIR__.'/'.$file,0,null,Phar::ZIP);$body='';
if(pathinfo($file,PATHINFO_EXTENSION)==='docx'){
 $doc=preview_xml($zip['word/document.xml']->getContent());$xp=new DOMXPath($doc);$xp->registerNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');
 foreach($xp->query('//w:body/*')as$node){if($node->localName==='p'){$body.='<p>'.preview_escape(implode(' ',array_map(static fn($t)=>$t->textContent,iterator_to_array($xp->query('.//w:t',$node))))).'</p>';}elseif($node->localName==='tbl'){$body.='<table class="word-table">';foreach($xp->query('w:tr',$node)as$row){$body.='<tr>';foreach($xp->query('w:tc',$row)as$cell)$body.='<td>'.preview_escape(implode(' ',array_map(static fn($t)=>$t->textContent,iterator_to_array($xp->query('.//w:t',$cell))))).'</td>';$body.='</tr>';}$body.='</table>';}}
 $body='<section class="word-page">'.$body.'</section>';
}else{
 $shared=[];if(isset($zip['xl/sharedStrings.xml'])){$doc=preview_xml($zip['xl/sharedStrings.xml']->getContent());$xp=new DOMXPath($doc);$xp->registerNamespace('m','http://schemas.openxmlformats.org/spreadsheetml/2006/main');foreach($xp->query('//m:si')as$si){$text='';foreach($xp->query('.//m:t',$si)as$t)$text.=$t->textContent;$shared[]=$text;}}
 $styles=[];if(isset($zip['xl/styles.xml'])){$doc=preview_xml($zip['xl/styles.xml']->getContent());$xp=new DOMXPath($doc);$xp->registerNamespace('m','http://schemas.openxmlformats.org/spreadsheetml/2006/main');foreach($xp->query('//m:cellXfs/m:xf')as$xf){$fill=$xp->query('//m:fills/m:fill')->item((int)$xf->getAttribute('fillId'));$color=$fill?$xp->evaluate('string(m:patternFill/m:fgColor/@rgb)',$fill):'';$font=$xp->query('//m:fonts/m:font')->item((int)$xf->getAttribute('fontId'));$styles[]=(preg_match('/^[A-Fa-f0-9]{8}$/',$color)?'background:#'.substr($color,2).';':'').($font&&$xp->query('m:b',$font)->length?'font-weight:bold;':'');}}
 $names=[];$doc=preview_xml($zip['xl/workbook.xml']->getContent());$xp=new DOMXPath($doc);$xp->registerNamespace('m','http://schemas.openxmlformats.org/spreadsheetml/2006/main');foreach($xp->query('//m:sheet')as$sheet)$names[]=$sheet->getAttribute('name');
 foreach($names as$i=>$name){$entry='xl/worksheets/sheet'.($i+1).'.xml';if(!isset($zip[$entry]))continue;$doc=preview_xml($zip[$entry]->getContent());$xp=new DOMXPath($doc);$xp->registerNamespace('m','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$cells=[];$lastRow=0;$lastCol=0;
 foreach($xp->query('//m:sheetData/m:row/m:c')as$cell){preg_match('/^([A-Z]+)([0-9]+)$/',$cell->getAttribute('r'),$parts);$c=preview_col($parts[1]);$r=(int)$parts[2];$type=$cell->getAttribute('t');$value=$type==='inlineStr'?$xp->evaluate('string(m:is)',$cell):$xp->evaluate('string(m:v)',$cell);if($type==='s')$value=$shared[(int)$value]??'';$cells[$r][$c]=[$value,$styles[(int)$cell->getAttribute('s')]??''];$lastRow=max($lastRow,$r);$lastCol=max($lastCol,$c);}
 $merged=[];$covered=[];foreach($xp->query('//m:mergeCell')as$merge){if(!preg_match('/^([A-Z]+)([0-9]+):([A-Z]+)([0-9]+)$/',$merge->getAttribute('ref'),$parts))continue;$l=preview_col($parts[1]);$r=preview_col($parts[3]);$t=(int)$parts[2];$b=(int)$parts[4];$merged[$t][$l]=[$r-$l+1,$b-$t+1];for($y=$t;$y<=$b;$y++)for($x=$l;$x<=$r;$x++)if($y!==$t||$x!==$l)$covered[$y][$x]=true;}
 $lastRow=min(250,max(8,$lastRow));$lastCol=min(80,$lastCol);$body.='<section><h2>'.preview_escape($name).'</h2><div class="sheet-scroll"><table class="excel-table">';for($r=1;$r<=$lastRow;$r++){$body.='<tr>';for($c=1;$c<=$lastCol;$c++){if(isset($covered[$r][$c]))continue;[$value,$style]=$cells[$r][$c]??['',''];[$colspan,$rowspan]=$merged[$r][$c]??[1,1];$body.='<td colspan="'.$colspan.'" rowspan="'.$rowspan.'" style="'.preview_escape($style).'">'.nl2br(preview_escape($value)).'</td>';}$body.='</tr>';}$body.='</table></div></section>';
 }
