echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Document preview</title><style>body{margin:0;padding:20px;background:#edf2ef;color:#183b2b;font:13px/1.5 Arial,sans-serif}section{background:white;margin:0 auto 20px;padding:20px;border-radius:8px}h2{font-size:16px;margin:0 0 16px}.sheet-scroll{overflow:auto}table{border-collapse:collapse}td{border:1px solid #8fbea5;padding:8px;min-width:100px;white-space:normal;vertical-align:middle}.excel-table{table-layout:fixed}.excel-table tr{height:32px}.word-page{max-width:794px;min-height:1000px;padding:40px}.word-table{width:100%;font-size:12px}.word-table td{min-width:0}p{white-space:pre-wrap;min-height:12px}@media(max-width:600px){body{padding:8px}section,.word-page{padding:16px}}</style>'.$body.'</html>';
